L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L30_1.m_Talk_KOREA = "이면세계에 오래 머물렀더니 머리가 이상해졌나 봐요."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "裏世界に長居したせいで、頭がどうにかなったようです。"
L30_1.m_Talk_ENG = "Maybe my head was in the clouds after being in the Counterside for too long."
L30_1.m_Talk_TWN = "在異界待久了，腦子好像有點不正常了。"
