L34_1 = {}
L34_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE3@34#Talk"
L34_1.m_CutScenProcessKey = 34
L34_1.m_CutScenID = 578
L34_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Talk_KOREA = "진실을 알고서 이면의 것들을 마주하게 된 소감은?"
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "真実を知って、裏世界の存在に向き合った感想は？"
L34_1.m_Talk_ENG = "How does it feel to know the truth and see what is on the other side?"
L34_1.m_Talk_TWN = "知道真相後，面對異界的事物有什麼感想？"
L34_1.m_Talk_SCN = "知道真相后，面对背后的事物有什么感想？"
L34_1.m_Talk_DEU = "How does it feel to know the truth and see what is on the other side?"
L34_1.m_Talk_FRA = "How does it feel to know the truth and see what is on the other side?"
L35_1 = {}
L35_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE3@35#Talk"
L35_1.m_CutScenProcessKey = 35
L35_1.m_CutScenID = 578
L35_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L35_1.m_Talk_KOREA = "…네. 이제야 알겠어요."
L35_1.m_fTalkTime = 0.03
L35_1.m_Talk_JPN = "……はい。やっとわかりました。"
L35_1.m_Talk_ENG = "...Yes. I understand now."
L35_1.m_Talk_TWN = "……是的。現在我明白了。"
L35_1.m_Talk_SCN = "……是的。现在我明白了。"
L35_1.m_Talk_DEU = "...Yes. I understand now."
L35_1.m_Talk_FRA = "...Yes. I understand now."
L36_1 = {}
L36_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE3@36#Talk"
L36_1.m_CutScenProcessKey = 36
L36_1.m_CutScenID = 578
L36_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L36_1.m_Talk_KOREA = "그 수많은 그림자들에게서 느낀 기시감은… 착각이 아니었군요."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "あの数えきれないシャドウたちから感じた既視感は……私の勘違いではなかった。"
L36_1.m_Talk_ENG = "The sense of deja vu I felt from those countless Shadows... I wasn't mistaken."
L36_1.m_Talk_TWN = "從那些無數的暗影中感受到的似曾相識感……果然不是錯覺。"
L36_1.m_Talk_SCN = "从那些无数的暗影中感受到的似曾相识感……果然不是错觉。"
L36_1.m_Talk_DEU = "The sense of deja vu I felt from those countless Shadows... I wasn't mistaken."
L36_1.m_Talk_FRA = "The sense of deja vu I felt from those countless Shadows... I wasn't mistaken."
L37_1 = {}
L37_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE3@37#Talk"
L37_1.m_CutScenProcessKey = 37
L37_1.m_CutScenID = 578
L37_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L37_1.m_Talk_KOREA = "이런 식으로… 옛 세계에 남겨진 전우들을 몇 번씩이고 제 손으로 죽이고 있었던 거네요."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "こうして私は……旧世界に残された戦友たちを、何度も手にかけてきたのですね。"
L37_1.m_Talk_ENG = "I've been killing the comrades left behind in the old world again and again, with my own hands..."
L37_1.m_Talk_TWN = "就這樣……我一次又一次地親手殺死了留在舊世界的戰友們。"
L37_1.m_Talk_SCN = "就这样……我一次又一次地亲手杀死了留在旧世界的战友们。"
L37_1.m_Talk_DEU = "I've been killing the comrades left behind in the old world again and again, with my own hands..."
L37_1.m_Talk_FRA = "I've been killing the comrades left behind in the old world again and again, with my own hands..."
