L40_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L40_1.m_Talk_KOREA = "왼쪽 팔이 없었던 그 그림자는… 부전대장 타티아나."
L40_1.m_fTalkTime = 0.03
