L40_1.m_Talk_SCN = "缺了左臂的那个暗影是……副战队长塔蒂亚娜。"
L40_1.m_Talk_DEU = "The Shadow that had no left arm... That was Deputy Commander Tatiana."
L40_1.m_Talk_FRA = "The Shadow that had no left arm... That was Deputy Commander Tatiana."
L41_1 = {}
L41_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE3@41#Talk"
