L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L42_1 = "가시로 뒤덮인 목 없는 그림자는… 말더듬이 신병 나탈리아."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "いばらに覆われた首なしのシャドウは……新兵のナタリア。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The headless Shadow covered in thorns... That was the stuttering recruit, Natalia."
L41_1.m_Talk_ENG = L42_1
L42_1 = "被荊棘覆蓋的無頭暗影……結巴的新兵那塔利亞。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "被荆棘覆盖的无头暗影……结巴的新兵那塔利亚。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "The headless Shadow covered in thorns... That was the stuttering recruit, Natalia."
L41_1.m_Talk_DEU = L42_1
L42_1 = "The headless Shadow covered in thorns... That was the stuttering recruit, Natalia."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP12_ACT4_EPILOGUE3@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 578
L42_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L43_1 = "그리고 익숙한 대검을 휘두르던 외눈의 그림자는…"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そして、見慣れた大剣を振るっていた隻眼のシャドウは……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "And the one-eyed Shadow that wielded a familiar greatsword must have been..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "而揮舞著那把熟悉的大劍的獨眼暗影則是……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "而挥舞着那柄熟悉的大剑的独眼暗影则是……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "And the one-eyed Shadow that wielded a familiar greatsword must have been..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "And the one-eyed Shadow that wielded a familiar greatsword must have been..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
