L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L45_1 = "시렌 전대를 창설했던 제 아버지… 펠릭스였겠죠."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "シレン戦隊の創設者、私の父親……フェリックスだったのでしょう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "...my father and founder of the Sirin Division... Felix."
L44_1.m_Talk_ENG = L45_1
L45_1 = "創立賽蓮小隊的我的父親……緋利克斯。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "组建了西琳小队的，我的父亲……菲利克斯。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "...my father and founder of the Sirin Division... Felix."
L44_1.m_Talk_DEU = L45_1
L45_1 = "...my father and founder of the Sirin Division... Felix."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
