L46_1 = "现在告诉我吧，萨温。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Now, tell me, Samhain."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Now, tell me, Samhain."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP12_ACT4_EPILOGUE3@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 578
L46_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "COMMANDER_PAST_JULIA_NULL"
L47_1 = "당신이 나에게서 원했던 건… 고작 내 영혼 하나가 아닌 거죠?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "あなたが私に求めていたのは……私の魂だけではない、そうでしょう？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "What you wanted from me... it wasn't just my soul, was it?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你從我這裡想要的……不僅僅是我的靈魂吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "你从我这里想要的……不仅仅是我的灵魂吧？"
L46_1.m_Talk_SCN = L47_1
