L49_1 = "제가 원하는 건 당신이 모든 기억을 간직한 채, 계속해서 미래로 나아가는 겁니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私の望みは、あなたがすべての記憶を持ったまま、更なる未来へ進むことです。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "What I want is for you to keep moving forward with all your memories."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我希望你能保留所有的記憶，繼續向未來前進。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "我希望你能保留所有的记忆，继续向未来前进。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "What I want is for you to keep moving forward with all your memories."
L48_1.m_Talk_DEU = L49_1
L49_1 = "What I want is for you to keep moving forward with all your memories."
L48_1.m_Talk_FRA = L49_1
