L50_1 = "저는 당신의 영혼을 차표 삼아 그 운명에 오른 승객일 뿐이죠."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "私はあなたの魂をチケットの代わりにして、運命に乗り込んだ乗客にすぎない。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I am merely a passenger who boarded on your fate using your soul as a ticket."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我只是以你的靈魂為車票，登上命運之旅的乘客而已。"
