L2_1 = "그 선로의 끝에서… 우린 무엇을 마주하게 될까요?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "その線路の果てで……私たちは何に向き合うのでしょう。"
