L2_1 = "And what will we face... at the end of the tracks?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那在那條軌道的盡頭……我們會遇見什麼呢？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "那在那条轨道的尽头……我们会遇见什么呢？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "And what will we face... at the end of the tracks?"
