L3_1 = "대적자, 마왕, 늑대… 그 모든 것을 만들어낸 <color=#ffd34c>원죄</color>"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "敵対者、魔王、オオカミ……そのすべてを生み出した<color=#ffd34c>原罪</color>。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The Antagonist, the Demon Lord, the Wolf... and the <color=#ffd34c>original sin</color> that created it all."
L2_1.m_Talk_ENG = L3_1
L3_1 = "敵對者、魔王、狼……這一切都是由<color=#ffd34c>原罪</color>所創造的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "敌对者、魔王、狼……这一切都是由<color=#ffd34c>原罪</color>所创造的。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "The Antagonist, the Demon Lord, the Wolf... and the <color=#ffd34c>original sin</color> that created it all."
L2_1.m_Talk_DEU = L3_1
L3_1 = "The Antagonist, the Demon Lord, the Wolf... and the <color=#ffd34c>original sin</color> that created it all."
