L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "沢山の人と契約し、長い間旅を続け……私はその原罪の名がわかりました。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "After having traveled a long journey and making contracts with countless people, I have discovered the name of the original sin."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我與無數人簽訂了契約，經過漫長的旅程，終於知道了那個原罪的名字。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "我与无数人签订了契约，经过漫长的旅程，终于知道了那个原罪的名字。"
