L13_1 = "EP12_ACT4_EPILOGUE3@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 578
L12_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "세계는 세피로트 나무를 지배하는 마왕 탐미엘에 의해 순환을 거듭하는 것."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "世界はセフィロトの木を支配する魔王、タミエルによって循環を繰り返す。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "This world continues its cycle through the Demon Lord Tammiel, the ruler of the Tree of Sefirot."
L12_1.m_Talk_ENG = L13_1
L13_1 = "世界在掌控著生命樹的魔王塔米爾的支配下不斷迴圈。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "世界在掌控着塞菲罗斯之树的魔王塔米尔的支配下不断循环。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "This world continues its cycle through the Demon Lord Tammiel, the ruler of the Tree of Sefirot."
L12_1.m_Talk_DEU = L13_1
L13_1 = "This world continues its cycle through the Demon Lord Tammiel, the ruler of the Tree of Sefirot."
