L14_1 = "EP12_ACT4_EPILOGUE3@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 578
L13_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "그 마왕의 사도는 당신처럼 영혼을 팔지 않더라도, 옛 세계의 기억을 온존하는 특별한 존재니까요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "魔王の使徒はあなたのように魂を売らずとも、旧世界の記憶を失わない特別な存在ですから。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "And that Demon Lord's Apostle is a special being who can preserve the memories of the old world, even without selling her soul like you did."
