L11_1 = "후훗, 그 반응… 정말로 자기가 죽을 줄 알았나 보네."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ふふ、その反応……本当に死ぬと思ったようだな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Fu fuu, that reaction... You must have thought you were really going to die."
L10_1.m_Talk_ENG = L11_1
L11_1 = "呵呵，看你的反應……還以為自己真的會死呢。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "呵呵，看你的反应……还以为自己真的会死。"
