L12_1 = "m_bCharPinup"
L11_1[L12_1] = true
L12_1 = "네가 스완만큼 대단한 거짓 연기로 날 속인 거라면, 그것도 인정해줘야겠어."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それともスワンほどの演技力で私を騙したのかな？　もしそうなら、それはそれで認めよう。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Or if you deceived me with an act as convincing as Swan's, props to you."
L11_1.m_Talk_ENG = L12_1
L12_1 = "如果你能像史旺那樣用高超的演技騙過我，那我也得承認你的厲害。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "如果你能像斯旺那样用高超的演技骗过我，那我也得承认你的厉害。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Or if you deceived me with an act as convincing as Swan's, props to you."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Or if you deceived me with an act as convincing as Swan's, props to you."
