L37_1 = "한 시간 뒤, 넌 임무를 거스르고 현장에서 도망친 반역자로 수배될 테니까."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "1時間後、君は命令に逆らって任務現場から逃げた反逆者として指名手配されるだろう。"
