L39_1 = "네 아버지의 허울 뿐인 명예를 위해 순순히 처형대에 오르겠다면, 여기 남아도 돼."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "君の父の名誉のために、大人しく処刑台に立つつもりなら残るといい。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "If you are willing to protect your father's vain honor and kneel before the guillotine, you can decide to stay."
L38_1.m_Talk_ENG = L39_1
L39_1 = "如果你願意維護你父親那虛假的榮譽而甘願走上斷頭台，那就留下來吧。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "如果你愿意维护你父亲那虚假的荣誉而甘愿走上断头台，那就留下来吧。"
