L32_1 = "FATIMA_LOTUS_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "당신의 처분은 잠시 유예 됐을 뿐입니다. 당신의 죄를 입증할 주요인물이 실종된 상태니까요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "あなたの処分については、決定が少し猶予されただけです。あなたの罪を証明できる主要人物が行方不明なので。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Your disposition has only been temporarily postponed. Because the key person who can prove your crime is missing at the moment."
L31_1.m_Talk_ENG = L32_1
L32_1 = "而且你的處置只是暫時擱置了。因為能證明你罪行的關鍵人物仍舊處於失蹤狀態。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "而且你的处置只是暂时搁置了。因为能证明你罪行的关键人物仍旧处于失踪状态。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Your disposition has only been temporarily postponed. Because the key person who can prove your crime is missing at the moment."
