L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "어때? 내 작품 <color=#ffd34c>선로전환기</color>에 대한 소감은?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "どう？　私の作品<color=#ffd34c>線路転換器</color>を見た感想は？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So? What do you think about my <color=#ffd34c>Track Switcher</color>?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "怎麼樣？對我的作品<color=#ffd34c>變軌器</color>有什麼感想？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "怎么样？对我的作品<color=#ffd34c>变轨器</color>有什么感想？"
