L46_1 = "EP12_ACT4_EPILOGUE3@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 578
L45_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "USER_ADMIN_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "장치를 가동한 것만으로, 다이브 중이던 차원함선을 다른 좌표에 보내다니."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "装置を稼働しただけで、ダイブ中の次元艦船を別の座標へ送れるとは。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I can't believe a dimensional ship that was already diving was sent to a different coordinate just by turning it on."
L45_1.m_Talk_ENG = L46_1
L46_1 = "僅僅是啟動裝置，就能將正在躍入的次元艦船送到其他座標。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "仅仅是启动装置，就能将正在跃入的次元舰船送到其他坐标。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "I can't believe a dimensional ship that was already diving was sent to a different coordinate just by turning it on."
L45_1.m_Talk_DEU = L46_1
L46_1 = "I can't believe a dimensional ship that was already diving was sent to a different coordinate just by turning it on."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP12_ACT4_EPILOGUE3@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 578
L46_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "USER_ADMIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "단기간에 이 정도 수준의 프로토타입을 만들어내는 건 나로선 엄두도 못 낼 일이야."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私としては、短時間でこの程度のプロトタイプを完成するなんて夢のような話だ。"
L46_1.m_Talk_JPN = L47_1
